106	    fn update_ss(&mut self) -> (Vec<u32>, Option<PublicKey>) {
107	        let mut same = None;
108	        let mut ids = Vec::with_capacity(self.pk_map.len());
109	        for (pk, peer) in self.pk_map.iter_mut() {
