18	pub struct Timers {
19	    // only updated during configuration
20	    enabled: bool,
21	    keepalive_interval: u64,
22	
23	    handshake_attempts: AtomicUsize,
24	    sent_lastminute_handshake: AtomicBool,
25	    need_another_keepalive: AtomicBool,
26	
27	    retransmit_handshake: Timer,
28	    send_keepalive: Timer,
29	    send_persistent_keepalive: Timer,
30	    zero_key_material: Timer,
31	    new_handshake: Timer,
32	}
33	
34	impl Timers {
35	    #[inline(always)]
36	    fn need_another_keepalive(&self) -> bool {
37	        self.need_another_keepalive.swap(false, Ordering::SeqCst)
38	    }
39	}
40	
41	impl<T: Tun, B: UDP> PeerInner<T, B> {
42	    pub fn get_keepalive_interval(&self) -> u64 {
43	        self.timers().keepalive_interval
44	    }
45	
46	    pub fn stop_timers(&self) {
47	        // take a write lock preventing simultaneous timer events or "start_timers" call
48	        let mut timers = self.timers_mut();
49	
50	        // set flag to prevent future timer events
51	        if !timers.enabled {
52	            return;
53	        }
54	        timers.enabled = false;
55	
56	        // stop all pending timers
57	        timers.retransmit_handshake.stop();
58	        timers.send_keepalive.stop();
59	        timers.send_persistent_keepalive.stop();
60	        timers.zero_key_material.stop();
61	        timers.new_handshake.stop();
62	
63	        // reset all timer state
64	        timers.handshake_attempts.store(0, Ordering::SeqCst);
65	        timers
66	            .sent_lastminute_handshake
67	            .store(false, Ordering::SeqCst);
68	        timers.need_another_keepalive.store(false, Ordering::SeqCst);
69	    }
70	
71	    pub fn start_timers(&self) {
72	        // take a write lock preventing simultaneous "stop_timers" call
73	        let mut timers = self.timers_mut();
74	
75	        // set flag to reenable timer events
76	        if timers.enabled {
77	            return;
78	        }
79	        timers.enabled = true;
80	
81	        // start send_persistent_keepalive
82	        if timers.keepalive_interval > 0 {
83	            timers
84	                .send_persistent_keepalive
85	                .start(Duration::from_secs(0));
86	        }
87	    }
88	
89	    /* should be called after an authenticated data packet is sent */
90	    pub fn timers_data_sent(&self) {
91	        let timers = self.timers();
92	        if timers.enabled {
93	            timers
94	                .new_handshake
95	                .start(KEEPALIVE_TIMEOUT + REKEY_TIMEOUT);
96	        }
97	    }
98	
99	    /* should be called after an authenticated data packet is received */
100	    pub fn timers_data_received(&self) {
101	        let timers = self.timers();
102	        if timers.enabled && !timers.send_keepalive.start(KEEPALIVE_TIMEOUT) {
103	            timers.need_another_keepalive.store(true, Ordering::SeqCst)
104	        }
105	    }
106	
107	    /* Should be called after any type of authenticated packet is sent, whether:
108	     * - keepalive
109	     * - data
110	     * - handshake
111	     */
112	    pub fn timers_any_authenticated_packet_sent(&self) {
113	        log::trace!("timers_any_authenticated_packet_sent");
114	        let timers = self.timers();
115	        if timers.enabled {
116	            timers.send_keepalive.stop()
117	        }
118	    }
119	
120	    /* Should be called after any type of authenticated packet is received, whether:
121	     * - keepalive
122	     * - data
123	     * - handshake
124	     */
125	    pub fn timers_any_authenticated_packet_received(&self) {
126	        log::trace!("timers_any_authenticated_packet_received");
127	        let timers = self.timers();
128	        if timers.enabled {
129	            timers.new_handshake.stop();
130	        }
131	    }
132	
133	    /* Should be called after a handshake initiation message is sent. */
134	    pub fn timers_handshake_initiated(&self) {
135	        log::trace!("timers_handshake_initiated");
136	        let timers = self.timers();
137	        if timers.enabled {
138	            timers.send_keepalive.stop();
139	            timers.retransmit_handshake.reset(REKEY_TIMEOUT);
140	        }
141	    }
142	
143	    /* Should be called after a handshake response message is received and processed
144	     * or when getting key confirmation via the first data message.
145	     */
146	    pub fn timers_handshake_complete(&self) {
147	        log::trace!("timers_handshake_complete");
148	        let timers = self.timers();
149	        if timers.enabled {
150	            timers.retransmit_handshake.stop();
151	            timers.handshake_attempts.store(0, Ordering::SeqCst);
152	            timers
153	                .sent_lastminute_handshake
154	                .store(false, Ordering::SeqCst);
155	            *self.walltime_last_handshake.lock() = Some(SystemTime::now());
156	        }
157	    }
158	
159	    /* Should be called after an ephemeral key is created, which is before sending a
160	     * handshake response or after receiving a handshake response.
161	     */
162	    pub fn timers_session_derived(&self) {
163	        log::trace!("timers_session_derived");
164	        let timers = self.timers();
165	        if timers.enabled {
166	            timers.zero_key_material.reset(REJECT_AFTER_TIME * 3);
167	        }
168	    }
169	
170	    /* Should be called before a packet with authentication, whether
171	     * keepalive, data, or handshake is sent, or after one is received.
172	     */
173	    pub fn timers_any_authenticated_packet_traversal(&self) {
174	        log::trace!("timers_any_authenticated_packet_traversal");
175	        let timers = self.timers();
176	        if timers.enabled && timers.keepalive_interval > 0 {
177	            // push persistent_keepalive into the future
178	            timers
179	                .send_persistent_keepalive
180	                .reset(Duration::from_secs(timers.keepalive_interval));
181	        }
182	    }
183	
184	    fn timers_set_retransmit_handshake(&self) {
185	        log::trace!("timers_set_retransmit_handshake");
186	        let timers = self.timers();
187	        if timers.enabled {
188	            timers.retransmit_handshake.reset(REKEY_TIMEOUT);
189	        }
190	    }
191	
192	    /* Called after a handshake worker sends a handshake initiation to the peer
193	     */
194	    pub fn sent_handshake_initiation(&self) {
195	        *self.last_handshake_sent.lock() = Instant::now();
196	        self.timers_handshake_initiated();
197	        self.timers_set_retransmit_handshake();
198	        self.timers_any_authenticated_packet_traversal();
199	        self.timers_any_authenticated_packet_sent();
200	    }
201	
202	    pub fn sent_handshake_response(&self) {
203	        *self.last_handshake_sent.lock() = Instant::now();
204	        self.timers_any_authenticated_packet_traversal();
205	        self.timers_any_authenticated_packet_sent();
206	    }
207	
208	    pub fn set_persistent_keepalive_interval(&self, secs: u64) {
209	        let mut timers = self.timers_mut();
210	
211	        // update the stored keepalive_interval
212	        timers.keepalive_interval = secs;
213	
214	        // stop the keepalive timer with the old interval
215	        timers.send_persistent_keepalive.stop();
216	
217	        // cause immediate expiry of persistent_keepalive timer
218	        if secs > 0 && timers.enabled {
219	            timers
220	                .send_persistent_keepalive
221	                .reset(Duration::from_secs(0));
222	        }
223	    }
224	
225	    fn packet_send_queued_handshake_initiation(&self, is_retry: bool) {
226	        if !is_retry {
227	            self.timers().handshake_attempts.store(0, Ordering::SeqCst);
228	        }
229	        self.packet_send_handshake_initiation();
230	    }
231	}
