21	// Represents the state of a peer.
22	//
23	// This type is only for internal use and not exposed.
24	pub(super) struct Peer<O> {
25	    // opaque type which identifies a peer
26	    pub opaque: O,
27	
28	    // mutable state
29	    pub state: Mutex<State>,
30	    pub timestamp: Mutex<Option<timestamp::TAI64N>>,
31	    pub last_initiation_consumption: Mutex<Option<Instant>>,
32	
33	    // state related to DoS mitigation fields
34	    pub macs: Mutex<macs::Generator>,
35	
36	    // constant state
37	    pub ss: [u8; 32], // precomputed DH(static, static)
38	    pub psk: Psk,     // psk of peer
39	}
40	
41	pub enum State {
42	    Reset,
43	    InitiationSent {
44	        local: u32, // local id assigned
45	        eph_sk: StaticSecret,
46	        hs: GenericArray<u8, U32>,
47	        ck: GenericArray<u8, U32>,
48	    },
49	}
50	
51	impl Drop for State {
52	    fn drop(&mut self) {
53	        if let State::InitiationSent { hs, ck, .. } = self {
54	            // eph_sk already cleared by dalek-x25519
55	            hs.clear();
56	            ck.clear();
57	        }
58	    }
59	}
60	
61	impl<O> Peer<O> {
62	    pub fn new(pk: PublicKey, ss: [u8; 32], opaque: O) -> Self {
63	        Self {
